function emptyGenericMapping(fields: Array<{ key: string }>): GenericImportMapping {
  return Object.fromEntries(fields.map((field) => [field.key, ""]));
}

function normalizeImportHeader(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, "");
}

