  const communicationFilteredNotifications = useMemo(() => {
    const search = communicationSearchTerm.toLowerCase().trim();

    return notifications.filter((item) => {
      const statusValue = String(item.email_status || item.status || "pending").toLowerCase();

      const matchesStatus =
        communicationStatusFilter === "Alle" ||
        (communicationStatusFilter === "Ausstehend" && ["pending", "queued", "geplant", "vorgemerkt"].includes(statusValue)) ||
        (communicationStatusFilter === "Gesendet" && ["sent", "gesendet"].includes(statusValue)) ||
        (communicationStatusFilter === "Fehler" && ["failed", "fehler"].includes(statusValue));

      const matchesType = communicationTypeFilter === "Alle" || item.type === communicationTypeFilter;

      const matchesSearch =
        !search ||
        [
          item.type,
          item.recipient,
          item.subject,
          item.message,
          item.email_status,
          item.status,
          item.email_error,
          item.email_template,
          item.email_provider_id,
          tickets.find((ticket) => ticket.id === item.related_ticket_id)?.ticket_number,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(search);

      return matchesStatus && matchesType && matchesSearch;
    });
  }, [notifications, communicationStatusFilter, communicationTypeFilter, communicationSearchTerm, tickets]);

  const communicationTypes = useMemo(() => {
    return Array.from(new Set(notifications.map((item) => item.type).filter(Boolean))).sort();
  }, [notifications]);

  const communicationLiveStats = useMemo(() => {
    return {
      total: notifications.length,
      visible: communicationFilteredNotifications.length,
      pending: emailStatusStats.pending + emailStatusStats.queued,
      sent: emailStatusStats.sent,
      failed: emailStatusStats.failed,
    };
  }, [notifications.length, communicationFilteredNotifications.length, emailStatusStats]);

  const userManagementStats = useMemo(() => {
    return {
      total: userProfiles.length,
      admins: userProfiles.filter((profile) => profile.role === "admin").length,
      technicians: userProfiles.filter((profile) => profile.role === "technician").length,
      customers: userProfiles.filter((profile) => profile.role === "customer").length,
      active: userProfiles.filter((profile) => profile.is_active !== false).length,
      inactive: userProfiles.filter((profile) => profile.is_active === false).length,
    };
  }, [userProfiles]);

  const userManagementProfiles = useMemo(() => {
    const search = userManagementSearch.trim().toLocaleLowerCase("de-DE");

    return userProfiles
      .filter((profile) => profile.role === userManagementRoleFilter)
      // Kunden erscheinen hier nur als echte Portal-Zugänge aus profiles.
      // Reine Servicekunden aus customers werden niemals in diese Liste gemischt.
      .filter((profile) => {
        if (!search) return true;
        const linkedCustomer = profile.role === "customer" ? getCustomerForUserProfile(profile) : null;
        return [
          getUserDisplayName(profile),
          profile.company,
          userCompanyNames[profile.id],
          linkedCustomer?.company,
          linkedCustomer?.email,
          linkedCustomer?.customer_number,
        ]
          .filter(Boolean)
          .join(" ")
          .toLocaleLowerCase("de-DE")
          .includes(search);
      })
      .sort((a, b) => getUserDisplayName(a).localeCompare(getUserDisplayName(b), "de"));
  }, [userProfiles, userManagementRoleFilter, userManagementSearch, userCompanyNames, customers]);

  const notificationTotalPages = Math.max(1, Math.ceil(communicationFilteredNotifications.length / notificationPageSize));

  const visibleNotifications = useMemo(() => {
    const startIndex = (notificationPage - 1) * notificationPageSize;
    return communicationFilteredNotifications.slice(startIndex, startIndex + notificationPageSize);
  }, [communicationFilteredNotifications, notificationPage]);


  function getEmailStatusLabel(status?: string | null) {
    const value = String(status || "pending").toLowerCase();

    if (value === "sent") return "Gesendet";
    if (value === "failed") return "Fehler";
    if (value === "queued") return "Vorgemerkt";
    if (value === "draft") return "Entwurf";

    return "Ausstehend";
  }

  function getEmailStatusClass(status?: string | null) {
    const value = String(status || "pending").toLowerCase();

    if (value === "sent") return "bg-emerald-500/15 text-emerald-300 border-emerald-500/30";
    if (value === "failed") return "bg-red-500/15 text-red-300 border-red-500/30";
    if (value === "queued") return "bg-blue-500/15 text-blue-300 border-blue-500/30";

    return "bg-amber-500/15 text-amber-300 border-amber-500/30";
  }


  function formatDateTime(value?: string | null) {
    if (!value) return "—";

    try {
      return new Intl.DateTimeFormat("de-DE", {
        dateStyle: "short",
        timeStyle: "short",
      }).format(new Date(value));
    } catch {
      return value;
    }
  }

  function formatServiceDate(value?: string | null) {
    if (!value) return "";
    const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return String(value);
    return `${match[3]}.${match[2]}.${match[1]}`;
  }

  function formatServiceTime(value?: string | null) {
    if (!value) return "";
    const match = String(value).match(/^(\d{2}):(\d{2})/);
    if (!match) return String(value);
    return `${match[1]}:${match[2]} Uhr`;
  }

  function formatServiceAppointment(date?: string | null, time?: string | null) {
    if (!date) return "Kein Termin geplant";
    const formattedDate = formatServiceDate(date);
    const formattedTime = formatServiceTime(time);
    return formattedTime ? `${formattedDate} · ${formattedTime}` : formattedDate;
  }

  function isCustomerPortalDocument(documentItem: DocumentItem) {
    return String(documentItem.file_path || "").includes("kundenportal/");
  }

  function getDocumentPremiumKind(documentItem: DocumentItem) {
    const name = String(documentItem.file_name || "").toLowerCase();
    const category = String(documentItem.category || "").toLowerCase();

    if (category.includes("video") || /\.(mp4|mov|webm|m4v|avi)$/i.test(name)) return "Video";
    if (category.includes("foto") || category.includes("bild") || /\.(jpg|jpeg|png|webp|heic|gif)$/i.test(name)) return "Foto";
    if (category.includes("lieferschein")) return "Lieferschein";
    if (/\.pdf$/i.test(name)) return "PDF";

    return "Dokument";
  }

  function getDocumentPremiumClass(documentItem: DocumentItem) {
    const kind = getDocumentPremiumKind(documentItem);

    if (isCustomerPortalDocument(documentItem)) {
      return "border-emerald-200 bg-emerald-50";
    }

    if (kind === "Foto") return "border-sky-200 bg-sky-50";
    if (kind === "Video") return "border-purple-200 bg-purple-50";
    if (kind === "Lieferschein") return "border-amber-200 bg-amber-50";

    return "border-slate-200 bg-white";
  }

  async function checkSession() {
    const { data } = await supabase.auth.getSession();

    setSession(data.session);
    setAuthLoading(false);

    if (data.session) {
      setAppDataLoaded(false);
      const profileIsValid = await loadUserProfile(data.session.user.id);

      if (profileIsValid) {
        loadApplicationData();
      }
    } else {
      setProfileLoading(false);
      setAppDataLoaded(false);
    }
  }

  async function loadCompany(userIdOverride?: string) {
    const userId = userIdOverride || session?.user?.id;

    if (!userId) {
      setCompanyData(null);
      return null;
    }

    try {
      // Wichtig: Ein Benutzer kann in mehreren Mandanten/Firmen stehen.
      // maybeSingle() ist hier falsch, weil es bei mehreren company_members einen Fehler liefert.
      // Wir laden alle Mitgliedschaften und verwenden den neuesten aktiven Mandanten,
      // ohne eine bestimmte Firma im TRYBUN-Code fest zu verdrahten.
      const { data: memberships, error: memberError } = await supabase
        .from("company_members")
        .select("company_id, role, created_at")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (memberError) {
        console.error("Company Member konnte nicht geladen werden:", memberError.message);
        setCompanyData(null);
        return null;
      }

      const companyIds = (memberships || [])
        .map((member: any) => member.company_id)
        .filter(Boolean);

      if (companyIds.length === 0) {
        setCompanyData(null);
        return null;
      }

      const { data: companiesResult, error: companyError } = await supabase
        .from("companies")
        .select("*")
        .in("id", companyIds)
        .eq("is_active", true);

      if (companyError) {
        console.error("Company konnte nicht geladen werden:", companyError.message);
        setCompanyData(null);
        return null;
      }

      const companiesList = (companiesResult || []) as CompanyData[];

      if (companiesList.length === 0) {
        setCompanyData(null);
        return null;
      }

      const preferredCompany =
        companiesList.find((company) => company.id === companyIds[0]) ||
        companiesList[0];

      setCompanyData(preferredCompany);
      return preferredCompany;
    } catch (error) {
      console.error("Company-Ladevorgang fehlgeschlagen:", error);
      setCompanyData(null);
      return null;
    }
  }

  async function saveCompanyBranding() {
    if (!isAdmin) {
      alert("Nur Admins können Firmeneinstellungen bearbeiten.");
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));

    if (!currentCompany?.id) {
      alert("Keine Firma geladen. Bitte Seite neu laden.");
      return;
    }

    if (!companyNameInput.trim()) {
      alert("Bitte einen Firmennamen eingeben.");
      return;
    }

    setCompanyBrandingSaving(true);

    const payload = {
      name: companyNameInput.trim(),
      logo_url: companyLogoUrlInput.trim() || null,
      primary_color: companyPrimaryColorInput.trim() || "#3B82F6",
      secondary_color: companySecondaryColorInput.trim() || "#0B1020",
      email: companyEmailInput.trim() || null,
      phone: companyPhoneInput.trim() || null,
      website: companyWebsiteInput.trim() || null,
      address: companyAddressInput.trim() || null,
      pdf_footer: companyPdfFooterInput.trim() || null,
    };

    const { data, error } = await supabase
      .from("companies")
      .update(payload)
      .eq("id", currentCompany.id)
      .select("*")
      .maybeSingle();

    setCompanyBrandingSaving(false);

    if (error) {
      alert(`Firmeneinstellungen konnten nicht gespeichert werden: ${error.message}`);
      return;
    }

    setCompanyData((data || { ...currentCompany, ...payload }) as CompanyData);
    alert("Firmeneinstellungen gespeichert.");
  }

  async function uploadCompanyLogo(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!isAdmin) {
      alert("Nur Admins können das Firmenlogo ändern.");
      event.target.value = "";
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));

    if (!currentCompany?.id) {
      alert("Keine Firma geladen. Bitte Seite neu laden.");
      event.target.value = "";
      return;
    }

    const allowedTypes = ["image/png", "image/jpeg", "image/webp", "image/svg+xml"];
    if (!allowedTypes.includes(file.type)) {
      alert("Bitte PNG, JPG, WEBP oder SVG als Logo verwenden.");
      event.target.value = "";
      return;
    }

    setCompanyLogoUploading(true);

    const safeName = file.name
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9._-]/g, "_");
    const filePath = `company-${currentCompany.id}/logo-${Date.now()}-${safeName}`;

    const uploadResult = await supabase.storage
      .from("company-assets")
      .upload(filePath, file, { upsert: true, contentType: file.type });

    if (uploadResult.error) {
      setCompanyLogoUploading(false);
      alert(`Logo konnte nicht hochgeladen werden: ${uploadResult.error.message}`);
      event.target.value = "";
      return;
    }

    const publicUrlResult = supabase.storage
      .from("company-assets")
      .getPublicUrl(filePath);

    const logoUrl = publicUrlResult.data.publicUrl;

    const { data, error } = await supabase
      .from("companies")
      .update({ logo_url: logoUrl })
      .eq("id", currentCompany.id)
      .select("*")
      .maybeSingle();

    setCompanyLogoUploading(false);
    event.target.value = "";

    if (error) {
      alert(`Logo wurde hochgeladen, aber nicht gespeichert: ${error.message}`);
      setCompanyLogoUrlInput(logoUrl);
      return;
    }

    setCompanyData((data || { ...currentCompany, logo_url: logoUrl }) as CompanyData);
    setCompanyLogoUrlInput(logoUrl);
    alert("Firmenlogo gespeichert.");
  }
  async function sendChatNotificationEmail(notificationItem: NotificationItem) {
    if (!notificationItem.recipient || !notificationItem.subject) {
      await supabase
        .from("notifications")
        .update({
          email_status: "failed",
          status: "Fehler",
          email_error: "Empfänger oder Betreff fehlt.",
          email_last_attempt_at: new Date().toISOString(),
        })
        .eq("id", notificationItem.id);

      await loadNotifications();
      return;
    }

    const attemptAt = new Date().toISOString();

    await supabase
      .from("notifications")
      .update({
        email_status: "queued",
        status: "Geplant",
        email_error: null,
        email_last_attempt_at: attemptAt,
      })
      .eq("id", notificationItem.id);

    setNotifications((prev) =>
      prev.map((item) =>
        item.id === notificationItem.id
          ? {
              ...item,
              email_status: "queued",
              status: "Geplant",
              email_error: null,
              email_last_attempt_at: attemptAt,
            }
          : item,
      ),
    );

    const { data, error } = await supabase.functions.invoke("resend-email", {
      body: {
        to: notificationItem.recipient,
        subject: notificationItem.subject,
        html: `
          <div style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;color:#0f172a">
            <div style="border:1px solid #e2e8f0;border-radius:18px;padding:24px;background:#ffffff">
              <p style="margin:0 0 8px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#0284c7;font-weight:700">
                TRYBUN · Ticket-Chat
              </p>
              <h1 style="margin:0 0 16px;font-size:24px;line-height:1.2">${notificationItem.subject}</h1>
              <div style="font-size:15px;line-height:1.6;color:#334155">
                ${String(notificationItem.message || "").replace(/\n/g, "<br/>")}
              </div>
              <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0" />
              <p style="font-size:12px;color:#64748b;margin:0">
                Diese Nachricht wurde automatisch aus dem Ticket-Chat gesendet.
              </p>
            </div>
          </div>
        `,
      },
    });

    if (error) {
      const errorMessage = error.message || "Resend Edge Function Fehler";

      await supabase
        .from("notifications")
        .update({
          email_status: "failed",
          status: "Fehler",
          email_error: errorMessage,
          email_last_attempt_at: new Date().toISOString(),
        })
        .eq("id", notificationItem.id);

      setNotifications((prev) =>
        prev.map((item) =>
          item.id === notificationItem.id
            ? {
                ...item,
                email_status: "failed",
                status: "Fehler",
                email_error: errorMessage,
                email_last_attempt_at: new Date().toISOString(),
              }
            : item,
        ),
      );

      console.error("Chat-Mail konnte nicht gesendet werden:", errorMessage);
      return;
    }

    const mailWasAccepted = Boolean(data?.id || data?.success);
    const nextStatus = mailWasAccepted ? "sent" : "failed";
    const nextLabel = mailWasAccepted ? "Gesendet" : "Fehler";
    const nextError = mailWasAccepted ? null : JSON.stringify(data || { error: "Keine Resend-ID erhalten" });

    await supabase
      .from("notifications")
      .update({
        email_status: nextStatus,
        status: nextLabel,
        email_provider_id: data?.id || data?.message_id || null,
        email_sent_at: mailWasAccepted ? new Date().toISOString() : null,
        email_error: nextError,
        email_last_attempt_at: new Date().toISOString(),
      })
      .eq("id", notificationItem.id);

    setNotifications((prev) =>
      prev.map((item) =>
        item.id === notificationItem.id
          ? {
              ...item,
              email_status: nextStatus,
              status: nextLabel,
              email_provider_id: data?.id || data?.message_id || null,
              email_sent_at: mailWasAccepted ? new Date().toISOString() : item.email_sent_at,
              email_error: nextError,
              email_last_attempt_at: new Date().toISOString(),
            }
          : item,
      ),
    );

    await loadNotifications();
  }

  async function retryNotificationEmail(notificationItem: NotificationItem) {
    if (!["failed", "pending", "queued"].includes(String(notificationItem.email_status || "pending").toLowerCase())) {
      const confirmed = window.confirm("Diese Nachricht wurde bereits als gesendet markiert. Trotzdem erneut senden?");
      if (!confirmed) return;
    }

    await sendChatNotificationEmail(notificationItem);
  }

