  async function uploadTicketChatAttachment(ticketId: number, file: File | null) {
    if (!file) return { name: null as string | null, url: null as string | null };

    const safeName = file.name
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9._-]/g, "_");

    const filePath = `ticket-chat/${ticketId}/${Date.now()}-${safeName}`;

    const uploadResult = await supabase.storage
      .from("documents")
      .upload(filePath, file, { upsert: false, contentType: file.type || "application/octet-stream" });

    if (uploadResult.error) {
      throw new Error(uploadResult.error.message);
    }

    const publicUrlResult = supabase.storage.from("documents").getPublicUrl(filePath);

    return {
      name: file.name,
      url: publicUrlResult.data.publicUrl,
    };
  }

  function canUseTicketChat(ticket: Ticket) {
    if (isAdmin) return true;
    if (isTechnician) {
      return ticket.assigned_to === userProfile?.id;
    }
    return isCustomer && isOwnCustomerTicket(ticket);
  }

  function getCustomerPrimaryEmailByTicket(ticket: Ticket) {
    const relatedCustomer =
      customers.find((item) => item.id === ticket.customer_id) ||
      customers.find((item) => getCustomerLabel(item) === ticket.customer) ||
      customers.find((item) => item.company === ticket.customer) ||
      null;

    return (
      ticket.service_contact_email ||
      relatedCustomer?.email ||
      relatedCustomer?.contact_1_email ||
      relatedCustomer?.email_2 ||
      ""
    );
  }

  function getTechnicianEmailByTicket(ticket: Ticket) {
    const technician = technicians.find((item) => item.id === ticket.assigned_to);

    return technician?.company || "";
  }

  function getChatNotificationRecipient(ticket: Ticket) {
    if (userProfile?.role === "customer") {
      return companyData?.email || getTechnicianEmailByTicket(ticket) || "service@trybun.local";
    }

    return getCustomerPrimaryEmailByTicket(ticket);
  }

  async function createChatNotification(ticket: Ticket, message: string, attachmentName?: string | null) {
    const recipient = getChatNotificationRecipient(ticket);

    if (!recipient) return;

    const senderName = userProfile?.full_name || userProfile?.company || profileCustomer?.company || "Nutzer";
    const shortMessage = message.length > 600 ? `${message.slice(0, 600)}...` : message;

    const notificationPayload = {
      type: "Ticket-Chat",
      recipient,
      subject: `Neue Chatnachricht · ${ticket.ticket_number}`,
      message: [
        `Ticket: ${ticket.ticket_number}`,
        `Kunde: ${ticket.customer}`,
        `Gerät: ${ticket.device || "-"}`,
        `Von: ${senderName}`,
        "",
        shortMessage || (attachmentName ? `Dateianhang: ${attachmentName}` : "Neue Datei im Ticket-Chat"),
      ].join("\n"),
      related_ticket_id: ticket.id,
      status: "Geplant",
      email_status: "pending",
      email_template: "Ticket-Chat",
      email_error: null,
    };

    const insertResult = await supabase
      .from("notifications")
      .insert([notificationPayload])
      .select("*")
      .single();

    if (insertResult.error || !insertResult.data) {
      console.error(
        "Chat-Benachrichtigung konnte nicht erstellt werden:",
        insertResult.error?.message || "Unbekannter Fehler",
      );
      return;
    }

    const createdNotification = insertResult.data as NotificationItem;

    await loadNotifications();
    await sendChatNotificationEmail(createdNotification);
  }

  async function sendTicketChatMessage(ticket: Ticket) {
    if (!canUseTicketChat(ticket)) {
      alert("Für dieses Ticket ist kein Chatzugriff möglich.");
      return;
    }

    const message = (ticketChatDrafts[ticket.id] || "").trim();
    const file = ticketChatFiles[ticket.id] || null;

    if (!message && !file) {
      alert("Bitte Nachricht oder Datei auswählen.");
      return;
    }

    let attachmentName: string | null = null;
    let attachmentUrl: string | null = null;

    try {
      const upload = await uploadTicketChatAttachment(ticket.id, file);
      attachmentName = upload.name;
      attachmentUrl = upload.url;
    } catch (error: any) {
      alert(`Datei konnte nicht hochgeladen werden: ${error?.message || "Unbekannter Fehler"}`);
      return;
    }

    const payload = {
      ticket_id: ticket.id,
      sender_id: userProfile?.id || null,
      sender_name: userProfile?.full_name || userProfile?.company || profileCustomer?.company || "Nutzer",
      sender_role: userProfile?.role || "admin",
      message: message || (attachmentName ? `Dateianhang: ${attachmentName}` : ""),
      attachment_name: attachmentName,
      attachment_url: attachmentUrl,
      read_by_admin: userProfile?.role === "admin",
      read_by_technician: userProfile?.role === "technician",
      read_by_customer: userProfile?.role === "customer",
    };

    const insertResult = await supabase
      .from("ticket_chat_messages")
      .insert([payload])
      .select("*")
      .single();

    if (insertResult.error || !insertResult.data) {
      alert(`Nachricht konnte nicht gespeichert werden: ${insertResult.error?.message || "Unbekannter Fehler"}`);
      return;
    }

    await createDeviceHistory(
      getDeviceForTicket(ticket)?.id || null,
      "Ticket-Chat Nachricht",
      `${ticket.ticket_number} · ${payload.sender_name}: ${payload.message}`,
      "Kommunikation",
    );

    await createChatNotification(ticket, payload.message, attachmentName);

    if (
      userProfile?.role === "customer" &&
      !["Abgeschlossen", "Erledigt", "Storniert", "Wartet auf Kundenfreigabe"].includes(ticket.status || "")
    ) {
      await supabase
        .from("tickets")
        .update({
          status: "Wartet auf Kundenfreigabe",
          service_status: "Neue Kundenrückfrage im Chat",
        })
        .eq("id", ticket.id);

      setTickets((prev) =>
        prev.map((item) =>
          item.id === ticket.id
            ? { ...item, status: "Wartet auf Kundenfreigabe", service_status: "Neue Kundenrückfrage im Chat" }
            : item,
        ),
      );
    }

    setTicketChatDrafts((prev) => ({ ...prev, [ticket.id]: "" }));
    setTicketChatFiles((prev) => ({ ...prev, [ticket.id]: null }));

    await loadTicketChatMessages();
  }

  async function markTicketChatRead(ticket: Ticket) {
    if (!canUseTicketChat(ticket)) return;

    const unreadMessages = ticketChatMessages.filter((message) => {
      if (message.ticket_id !== ticket.id) return false;
      if (userProfile?.role === "customer") return !message.read_by_customer;
      if (userProfile?.role === "technician") return !message.read_by_technician;
      return !message.read_by_admin;
    });

    if (unreadMessages.length === 0) return;

    const updatePayload =
      userProfile?.role === "customer"
        ? { read_by_customer: true }
        : userProfile?.role === "technician"
          ? { read_by_technician: true }
          : { read_by_admin: true };

    const { error } = await supabase
      .from("ticket_chat_messages")
      .update(updatePayload)
      .in("id", unreadMessages.map((message) => message.id));

    if (error) {
      console.error("Chat konnte nicht als gelesen markiert werden:", error.message);
      return;
    }

    await loadTicketChatMessages();
  }

  async function loadContracts() {
    const { data, error } = await supabase
      .from("service_contracts")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Verträge konnten nicht geladen werden:", error.message);
      setContracts([]);
      return;
    }

    setContracts((data || []) as ServiceContract[]);
  }

  async function loadUserProfiles() {
    // Benutzerverwaltung Premium v1:
    // Dieser Bereich lädt vorhandene Profile nur lesend.
    // Keine Auth-User werden erzeugt, keine Einladungen versendet und keine Rollen automatisch geändert.
    const fallbackProfiles: UserProfile[] = [];

    try {
      const timeout = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error("Benutzer-Ladevorgang Timeout")), 3500);
      });

      const profilesRequest = supabase
        .from("profiles")
        .select("id, full_name, role, company, customer_id, is_active, created_at")
        .order("created_at", { ascending: false });

      const result: any = await Promise.race([profilesRequest, timeout]);

      if (result?.error) {
        console.error("Benutzerprofile konnten nicht geladen werden:", result.error.message);
        setUserProfiles(fallbackProfiles);
        return;
      }

      const loadedProfiles = (result?.data || []) as UserProfile[];
      setUserProfiles(loadedProfiles);

      const profileIds = loadedProfiles.map((profile) => profile.id).filter(Boolean);

      if (profileIds.length === 0) {
        setUserCompanyNames({});
        return;
      }

      const { data: memberships, error: membershipsError } = await supabase
        .from("company_members")
        .select("user_id, company_id, role, created_at")
        .in("user_id", profileIds)
        .order("created_at", { ascending: false });

      if (membershipsError) {
        console.error("Firmenzuordnungen konnten nicht geladen werden:", membershipsError.message);
        setUserCompanyNames({});
        return;
      }

      const companyIds = Array.from(
        new Set(
          (memberships || [])
            .map((membership: any) => Number(membership.company_id))
            .filter((companyId: number) => Number.isFinite(companyId) && companyId > 0),
        ),
      );

      if (companyIds.length === 0) {
        setUserCompanyNames({});
        return;
      }

      const { data: companiesResult, error: companiesError } = await supabase
        .from("companies")
        .select("id, name")
        .in("id", companyIds);

      if (companiesError) {
        console.error("Firmennamen konnten nicht geladen werden:", companiesError.message);
        setUserCompanyNames({});
        return;
      }

      const companyNameById = new Map<number, string>(
        (companiesResult || []).map((company: any) => [
          Number(company.id),
          String(company.name || "").trim(),
        ]),
      );

      const nextUserCompanyNames: Record<string, string> = {};

      (memberships || []).forEach((membership: any) => {
        const userId = String(membership.user_id || "");
        if (!userId || nextUserCompanyNames[userId]) return;

        const companyName = companyNameById.get(Number(membership.company_id));
        if (companyName) nextUserCompanyNames[userId] = companyName;
      });

      setUserCompanyNames(nextUserCompanyNames);
    } catch (error) {
      console.error("Benutzer-Ladevorgang übersprungen:", error);
      setUserProfiles(fallbackProfiles);
      setUserCompanyNames({});
    }
  }

  async function createUserFromManagement() {
    if (!isAdmin) {
      alert("Nur Admins können Benutzer anlegen.");
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));

    if (!currentCompany?.id) {
      alert("Keine Firma geladen. Bitte Seite neu laden und erneut versuchen.");
      return;
    }

    const cleanedEmail = newUserEmail.trim().toLowerCase();
    const cleanedName = newUserFullName.trim();

    if (!cleanedEmail) {
      alert("Bitte eine E-Mail-Adresse eintragen.");
      return;
    }

    if (!cleanedEmail.includes("@")) {
      alert("Bitte eine gültige E-Mail-Adresse eintragen.");
      return;
    }

    if (newUserRole === "customer" && !newUserCustomerId) {
      alert("Bitte für Kundenportal-Nutzer einen Kunden zuordnen.");
      return;
    }

    setCreatingUser(true);

    const { data, error } = await supabase.functions.invoke("create-user", {
      body: {
        email: cleanedEmail,
        full_name: cleanedName || cleanedEmail,
        role: newUserRole,
        customer_id: newUserRole === "customer" ? Number(newUserCustomerId) : null,
        company_id: currentCompany.id,
      },
    });

    setCreatingUser(false);

    if (error) {
      alert(`Benutzer konnte nicht angelegt werden: ${error.message}`);
      return;
    }

    if (data?.error) {
      alert(`Benutzer konnte nicht angelegt werden: ${data.error}`);
      return;
    }

    setNewUserFullName("");
    setNewUserEmail("");
    setNewUserRole("technician");
    setNewUserCustomerId("");

    await loadUserProfiles();
    await loadTechnicians();

    alert(
      data?.invitation_sent
        ? "Kundeneinladung wurde erfolgreich versendet."
        : "Benutzer wurde erfolgreich angelegt.",
    );
  }

  async function inviteCustomerToPortal(customerItem: Customer) {
    if (!isAdmin) {
      alert("Nur Admins können Portalzugänge einladen.");
      return;
    }

    const customerId = Number(customerItem.id);
    const existingPortalProfile = userProfiles.find(
      (profile) => profile.role === "customer" && Number(profile.customer_id) === customerId,
    );

    if (existingPortalProfile) {
      alert("Für diesen Kunden besteht bereits ein Portalzugang.");
      return;
    }

    const cleanedEmail = String(customerItem.email || "").trim().toLowerCase();
    if (!cleanedEmail || !cleanedEmail.includes("@")) {
      alert("Für die Portal-Einladung muss beim Kunden eine gültige E-Mail-Adresse hinterlegt sein.");
      return;
    }

    const currentCompany = companyData || (await loadCompany(session?.user?.id));
    if (!currentCompany?.id) {
      alert("Die Firmenzuordnung konnte nicht geladen werden. Bitte erneut versuchen.");
      return;
    }

    const customerName =
      getCustomerDisplayName(customerItem) ||
      String(customerItem.company || "").trim() ||
      cleanedEmail;

    if (!confirm(`Portalzugang für ${customerName} an ${cleanedEmail} einladen?`)) {
      return;
    }

    setPortalInvitingCustomerId(customerId);

    try {
      const { data, error } = await supabase.functions.invoke("create-user", {
        body: {
          email: cleanedEmail,
          full_name: customerName,
          role: "customer",
          customer_id: customerId,
          company_id: currentCompany.id,
        },
      });

      if (error) {
        alert(`Portalzugang konnte nicht eingeladen werden: ${error.message}`);
        return;
      }

      if (data?.error) {
        alert(`Portalzugang konnte nicht eingeladen werden: ${data.error}`);
        return;
      }

      await loadUserProfiles();
      alert(
        data?.invitation_sent
          ? "Kundeneinladung wurde erfolgreich versendet."
          : "Portalzugang wurde erfolgreich angelegt.",
      );
    } finally {
      setPortalInvitingCustomerId(null);
    }
  }

  async function loadTechnicians() {
    // Sicherer Restore:
    // Techniker werden wieder aus public.profiles geladen.
    // Falls Supabase/RLS hängt oder einen Fehler liefert, blockiert die App nicht.
    const fallbackTechnicians: UserProfile[] = [];

    try {
      const timeout = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error("Techniker-Ladevorgang Timeout")), 3500);
      });

      const profilesRequest = supabase
        .from("profiles")
        .select("id, full_name, role, company, customer_id, is_active, created_at")
        .in("role", ["technician", "admin"])
        .order("full_name", { ascending: true });

      const result: any = await Promise.race([profilesRequest, timeout]);

      if (result?.error) {
        console.error("Techniker konnten nicht aus profiles geladen werden:", result.error.message);
        setTechnicians(fallbackTechnicians);
        return;
      }

      const assignableProfiles = ((result?.data || []) as UserProfile[]).filter((profile) => {
        if (profile.is_active === false) return false;

        const role = String(profile.role || "").toLowerCase();
        const name = String(profile.full_name || "").trim().toLowerCase();

        if (role === "technician") return true;

        // Optionaler Demo-Admin kann zusätzlich als Techniker im Dropdown erscheinen.
        // Andere Admins sollen nicht automatisch im Techniker-Dropdown erscheinen.
        if (role === "admin" && name === "max mustermann") return true;

        return false;
      });

      const profileByName = new Map<string, UserProfile>();

      assignableProfiles.forEach((profile) => {
        const nameKey = String(profile.full_name || profile.company || profile.id)
          .trim()
          .toLowerCase();

        const existingProfile = profileByName.get(nameKey);

        // Doppelte Personen vermeiden.
        // Wenn eine Person als technician und admin existiert, wird technician bevorzugt.
        if (!existingProfile) {
          profileByName.set(nameKey, profile);
          return;
        }

        if (existingProfile.role !== "technician" && profile.role === "technician") {
          profileByName.set(nameKey, profile);
        }
      });

      const loadedProfiles = Array.from(profileByName.values()).sort((a, b) =>
        String(a.full_name || a.company || "").localeCompare(
          String(b.full_name || b.company || ""),
          "de",
        ),
      );

      if (loadedProfiles.length === 0) {
        setTechnicians(fallbackTechnicians);
        return;
      }

      setTechnicians(loadedProfiles);
    } catch (error) {
      console.error("Techniker-Ladevorgang übersprungen:", error);
      setTechnicians(fallbackTechnicians);
    }
  }

  function getTechnicianNameById(technicianId?: string | null) {
    if (!technicianId) return "Nicht zugewiesen";
    const technician = technicians.find((item) => item.id === technicianId);
    return technician?.full_name || technician?.company || "Techniker";
  }

  function getUserRoleLabel(role?: string | null) {
    if (role === "admin") return "Admin";
    if (role === "technician") return "Techniker";
    if (role === "customer") return "Kunde";
    return "Unbekannt";
  }

  function getUserRoleClass(role?: string | null) {
    if (role === "admin") return "border-sky-400/40 bg-sky-500/15 text-sky-100";
    if (role === "technician") return "border-emerald-400/40 bg-emerald-500/15 text-emerald-100";
    if (role === "customer") return "border-amber-400/40 bg-amber-500/15 text-amber-100";
    return "border-slate-400/40 bg-slate-500/15 text-slate-100";
  }

  function getUserDisplayName(profile: UserProfile) {
    return profile.full_name || profile.company || `Benutzer ${String(profile.id || "").slice(0, 8)}`;
  }

  function getCustomerForUserProfile(profile: UserProfile) {
    if (!profile.customer_id) return null;
    return customers.find((customerItem) => customerItem.id === profile.customer_id) || null;
  }

  async function updateTicketAssignment(
    ticketId: number,
    assignedTo: string | null,
    serviceDate?: string | null,
    serviceTime?: string | null,
  ) {
    if (!canPlanDispatch) {
      alert("Nur Admins können Tickets disponieren und Techniker zuweisen.");
      return;
    }

    if (serviceDate && !isValidAppDate(serviceDate)) {
      // Während der Eingabe eines nativen Datumsfelds entstehen kurzzeitig
      // unvollständige Jahreswerte. Diese werden nicht gespeichert, aber auch
      // nicht mit störenden Zwischenmeldungen quittiert.
      return;
    }

    const currentTicket = tickets.find((ticket) => ticket.id === ticketId);
    const nextStatus = assignedTo
      ? currentTicket?.status === "Abgeschlossen"
        ? "Abgeschlossen"
        : "Zugewiesen"
      : currentTicket?.status || "Offen";

    const payload = {
      assigned_to: assignedTo,
      assigned_at: assignedTo ? new Date().toISOString() : null,
      service_date: serviceDate || null,
      service_time: serviceTime || null,
      service_status: assignedTo ? "Geplant" : null,
      status: nextStatus,
    };

    const { error } = await supabase
      .from("tickets")
      .update(payload)
      .eq("id", ticketId);

    if (error) {
      alert(`Zuweisung konnte nicht gespeichert werden: ${error.message}`);
      return;
    }

    setTickets((prev) =>
      prev.map((ticket) =>
        ticket.id === ticketId ? { ...ticket, ...payload } : ticket,
      ),
    );

    await loadTickets();

    const assignedName = getTechnicianNameById(assignedTo);
    const relatedDevice = devices.find(
      (item) => item.name === currentTicket?.device,
    );
    await createDeviceHistory(
      relatedDevice?.id || null,
      assignedTo ? "Ticket zugewiesen" : "Ticket-Zuweisung entfernt",
      `${currentTicket?.ticket_number || "Ticket"} · ${assignedName}${serviceDate ? ` · Termin: ${serviceDate}${serviceTime ? ` ${serviceTime}` : ""}` : ""}`,
      "Einsatz",
    );
  }

  async function createDeviceHistory(
    deviceId: number | null,
    title: string,
    description: string,
    type: string,
  ) {
    if (!deviceId) return;

    const { error } = await supabase.from("device_history").insert([
      {
        device_id: deviceId,
        title,
        description,
        type,
      },
    ]);

    if (!error) {
      await loadDeviceHistory();
    }
  }

  async function handleFileUpload(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    const selectedUploadDevice = selectedDeviceId
      ? devices.find((deviceItem) => deviceItem.id === Number(selectedDeviceId))
      : null;

    const selectedUploadTicket = customerUploadTicketId
      ? tickets.find((ticketItem) => ticketItem.id === Number(customerUploadTicketId)) || null
      : null;

    const ticketDevice = selectedUploadTicket ? getDeviceForTicket(selectedUploadTicket) : null;
    const finalDeviceId = selectedUploadDevice?.id || ticketDevice?.id || null;
    const finalTicketId = selectedUploadTicket?.id || null;

    if (isCustomer && !userProfile?.customer_id) {
      alert("Dein Kundenkonto ist noch keinem Kunden zugeordnet. Bitte deinen zuständigen Administrator kontaktieren.");
      event.target.value = "";
      return;
    }

    if (isCustomer && selectedUploadTicket) {
      const ticketBelongsToCustomer =
        selectedUploadTicket.customer_id === userProfile?.customer_id ||
        (!!profileCustomer?.company && selectedUploadTicket.customer === profileCustomer.company);

      if (!ticketBelongsToCustomer) {
        alert("Dieses Ticket gehört nicht zu deinem Kundenkonto.");
        event.target.value = "";
        return;
      }
    }

    if (isCustomer && selectedUploadDevice && selectedUploadDevice.customer_id !== userProfile?.customer_id) {
      alert("Dieses Gerät gehört nicht zu deinem Kundenkonto.");
      event.target.value = "";
      return;
    }

    if (isCustomer && !customerUploadDocumentCategories.includes(uploadCategory)) {
      alert("Diese Dokumentkategorie darf im Kundenportal nicht hochgeladen werden.");
      event.target.value = "";
      return;
    }

    const uploadCustomerId = isCustomer
      ? String(userProfile?.customer_id || "")
      : selectedUploadCustomerId ||
        (selectedUploadDevice?.customer_id ? String(selectedUploadDevice.customer_id) : "");

    const isAcceptanceProtocolUpload = !isCustomer && uploadCategory === "Abnahmeprotokolle";
    const finalNextInspectionDate = calculateNextInspectionDateFromUpload();

    if (isAcceptanceProtocolUpload && !uploadCustomerId) {
      alert("Bitte für das Abnahmeprotokoll zuerst einen Kunden auswählen.");
      event.target.value = "";
      return;
    }

    if (isAcceptanceProtocolUpload && !uploadInspectionDate) {
      alert("Bitte das Prüfdatum des Abnahmeprotokolls eingeben.");
      event.target.value = "";
      return;
    }

    if (isAcceptanceProtocolUpload && !finalNextInspectionDate) {
      alert("Bitte nächste Prüfung oder ein gültiges Prüfintervall eingeben.");
      event.target.value = "";
      return;
    }

    setUploading(true);

    const safeFileName = file.name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9._-]/g, "_");
    const safeCategory =
      uploadCategory === "Abnahmeprotokolle" ? "abnahmeprotokolle" : uploadCategory.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9._-]/g, "_");
    const filePath = isCustomer
      ? `kundenportal/customer-${userProfile?.customer_id || "unknown"}/${finalTicketId ? `ticket-${finalTicketId}/` : ""}${Date.now()}-${safeFileName}`
      : `${safeCategory}/${Date.now()}-${safeFileName}`;

    const uploadResult = await supabase.storage
      .from("documents")
      .upload(filePath, file);

    if (uploadResult.error) {
      setUploading(false);
      alert("Upload fehlgeschlagen.");
      return;
    }

    const insertResult = await supabase.from("documents").insert([
      {
        file_name: file.name,
        file_path: filePath,
        category: uploadCategory,
        file_size: file.size,
        device_id: finalDeviceId,
        ticket_id: finalTicketId,
        customer_id: uploadCustomerId ? Number(uploadCustomerId) : null,
        inspection_date: isAcceptanceProtocolUpload ? uploadInspectionDate || null : null,
        next_inspection_date: isAcceptanceProtocolUpload ? finalNextInspectionDate || null : null,
        inspection_interval_months: isAcceptanceProtocolUpload ? Number(uploadInspectionIntervalMonths || 12) : null,
        inspection_badge_number: isAcceptanceProtocolUpload ? uploadInspectionBadgeNumber.trim() || null : null,
        inspection_note: isAcceptanceProtocolUpload ? uploadInspectionNote.trim() || null : null,
      },
    ]);

    setUploading(false);

    if (insertResult.error) {
      alert(`Datei wurde hochgeladen, aber nicht gespeichert: ${insertResult.error.message}`);
      return;
    }

    if (isAcceptanceProtocolUpload && selectedDeviceId) {
      await supabase
        .from("devices")
        .update({
          inspection_date: uploadInspectionDate || null,
          inspection_expires: finalNextInspectionDate || null,
          next_check: finalNextInspectionDate || null,
          inspection_badge_number: uploadInspectionBadgeNumber.trim() || null,
          inspection_result: "Bestanden",
          inspection_comment: uploadInspectionNote.trim() || null,
          status: "Aktiv",
        })
        .eq("id", Number(selectedDeviceId));

      const existingPlan = maintenancePlans.find(
        (plan) =>
          plan.device_id === Number(selectedDeviceId) &&
          String(plan.maintenance_type || "").toLowerCase().includes("prüfung"),
      );

      const maintenancePayload = {
        device_id: Number(selectedDeviceId),
        customer_id: uploadCustomerId ? Number(uploadCustomerId) : selectedUploadDevice?.customer_id || null,
        title: `Nächste Prüfung aus Abnahmeprotokoll · ${selectedUploadDevice?.name || file.name}`,
        maintenance_type: "Prüfung / Abnahmeprotokoll",
        interval_days: Number(uploadInspectionIntervalMonths || 12) * 30,
        next_due: finalNextInspectionDate,
        assigned_to: null,
        status: "Geplant",
        note: [
          `Automatisch aus hochgeladenem Abnahmeprotokoll erzeugt: ${file.name}`,
          uploadInspectionBadgeNumber ? `Prüfsiegel: ${uploadInspectionBadgeNumber}` : "",
          uploadInspectionNote ? `Bemerkung: ${uploadInspectionNote}` : "",
        ].filter(Boolean).join(" · "),
      };

      if (existingPlan) {
        await supabase.from("maintenance_plans").update(maintenancePayload).eq("id", existingPlan.id);
      } else {
        await supabase.from("maintenance_plans").insert([maintenancePayload]);
      }
    }

    await createDeviceHistory(
      finalDeviceId,
      isAcceptanceProtocolUpload
        ? "Abnahmeprotokoll hochgeladen und Prüffrist gesetzt"
        : "Dokument hochgeladen und zugeordnet",
      `${uploadCategory}: ${file.name} · Kunde: ${uploadCustomerId ? getCustomerNameById(Number(uploadCustomerId)) : "Nicht zugeordnet"}${
        isAcceptanceProtocolUpload ? ` · nächste Prüfung: ${finalNextInspectionDate}` : ""
      }`,
      "Dokument",
    );

    event.target.value = "";
    setSelectedDeviceId("");
    setUploadDeviceSearch("");
    setUploadInspectionDate("");
    setUploadNextInspectionDate("");
    setUploadInspectionIntervalMonths("12");
    setUploadInspectionBadgeNumber("");
    setUploadInspectionNote("");
    setCustomerUploadTicketId("");
    setCustomerUploadFile(null);
    await loadDocuments();
    await loadDevices();
    await loadMaintenancePlans();

    alert(
      isAcceptanceProtocolUpload
        ? "Abnahmeprotokoll wurde hochgeladen, dem Kunden zugeordnet und die nächste Prüfung wurde gesetzt."
        : finalTicketId
          ? "Dokument erfolgreich hochgeladen, dem Kundenkonto zugeordnet und mit dem Ticket verknüpft."
          : "Dokument erfolgreich hochgeladen und dem Kunden zugeordnet.",
    );
  }

  async function handleDeviceFileUpload(
    event: ChangeEvent<HTMLInputElement>,
    deviceId: number,
  ) {
    const file = event.target.files?.[0];

    if (!file) return;

    setUploading(true);

    const safeFileName = file.name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9._-]/g, "_");

    const safeCategory =
      uploadCategory === "Abnahmeprotokolle" ? "Abnahmeprotokolle" : uploadCategory;

    const filePath = `${safeCategory}/${Date.now()}-${safeFileName}`;

    const uploadResult = await supabase.storage
      .from("documents")
      .upload(filePath, file);

    if (uploadResult.error) {
      setUploading(false);
      alert("Upload fehlgeschlagen.");
      return;
    }

    const insertResult = await supabase.from("documents").insert([
      {
        file_name: file.name,
        file_path: filePath,
        category: uploadCategory,
        file_size: file.size,
        device_id: deviceId,
        customer_id: devices.find((deviceItem) => deviceItem.id === deviceId)?.customer_id || null,
      },
    ]);

    setUploading(false);

    if (insertResult.error) {
      alert("Datei wurde hochgeladen, aber nicht gespeichert.");
      return;
    }

    await createDeviceHistory(
      deviceId,
      "Dokument direkt am Gerät hochgeladen",
      `${uploadCategory}: ${file.name}`,
      "Dokument",
    );

    event.target.value = "";
    await loadDocuments();
    alert("Dokument erfolgreich beim Gerät hochgeladen.");
  }

  function getDocumentsForTicket(ticket: Ticket) {
    const relatedDevice = devices.find((item) => item.name === ticket.device);

    return documents.filter((documentItem) => {
      if (documentItem.ticket_id === ticket.id) return true;
      if (relatedDevice && documentItem.device_id === relatedDevice.id) return true;
      return false;
    });
  }

  function getCustomerForTicket(ticket: Ticket) {
    if (ticket.customer_id) {
      const byId = customers.find((item) => item.id === ticket.customer_id);
      if (byId) return byId;
    }

    return (
      customers.find((item) => item.company === ticket.customer) ||
      customers.find((item) => getCustomerLabel(item) === ticket.customer) ||
      null
    );
  }

  function getDeviceForTicket(ticket: Ticket) {
    if (!ticket.device) return null;

    return (
      devices.find((item) => item.name === ticket.device) ||
      devices.find((item) => String(item.serial_number || "") === ticket.device) ||
      null
    );
  }


  function getDevicesForTicketSelection(ticket: Ticket) {
    const ticketText = [ticket.device, ticket.description]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    if (!ticketText.trim()) return [];

    const directDevice = getDeviceForTicket(ticket);
    const relatedCustomer = getCustomerForTicket(ticket);
    const possibleDevices = relatedCustomer?.id
      ? devices.filter((deviceItem) => deviceItem.customer_id === relatedCustomer.id)
      : devices;

    const matchedDevices = possibleDevices.filter((deviceItem) => {
      const manufacturerName =
        deviceItem.manufacturer || getManufacturerNameById(deviceItem.manufacturer_id);
      const modelName =
        getDeviceModelNameById(deviceItem.model_id) || deviceItem.model || deviceItem.name;

      const searchParts = [
        deviceItem.name,
        manufacturerName,
        modelName,
        deviceItem.serial_number,
        deviceItem.location,
      ]
        .filter(Boolean)
        .map((value) => String(value).toLowerCase().trim())
        .filter((value) => value.length >= 2);

      return searchParts.some((value) => ticketText.includes(value));
    });

    const uniqueMap = new Map<number, Device>();

    if (directDevice) {
      uniqueMap.set(directDevice.id, directDevice);
    }

    matchedDevices.forEach((deviceItem) => {
      uniqueMap.set(deviceItem.id, deviceItem);
    });

    return Array.from(uniqueMap.values());
  }

  function uniqueDocuments(items: DocumentItem[]) {
    const seen = new Set<number>();
    return items.filter((item) => {
      if (seen.has(item.id)) return false;
      seen.add(item.id);
      return true;
    });
  }

  function getDocumentsForTicketContext(ticket: Ticket) {
    const relatedDevice = getDeviceForTicket(ticket);
    const relatedCustomer = getCustomerForTicket(ticket);

    return uniqueDocuments(
      documents.filter((documentItem) => {
        if (documentItem.ticket_id === ticket.id) return true;
        if (relatedDevice && documentItem.device_id === relatedDevice.id) return true;
        if (relatedCustomer && documentItem.customer_id === relatedCustomer.id) return true;
        if (relatedCustomer) {
          const linkedDevice = documentItem.device_id
            ? devices.find((deviceItem) => deviceItem.id === documentItem.device_id)
            : null;
          if (linkedDevice?.customer_id === relatedCustomer.id) return true;
        }
        return false;
      }),
    ).sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
  }

  function getTicketsForCustomerContext(customerId?: number | null) {
    if (!customerId) return [];
    return tickets
      .filter((ticket) => ticket.customer_id === customerId)
      .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
  }

