  async function sendNotificationEmail(notificationItem: NotificationItem) {
    if (!notificationItem.recipient || !notificationItem.subject) {
      alert("Empfänger und Betreff fehlen.");
      return;
    }

    setNotifications((prev) =>
      prev.map((item) =>
        item.id === notificationItem.id
          ? {
              ...item,
              email_status: "queued",
              status: "Geplant",
              email_error: null,
              email_last_attempt_at: new Date().toISOString(),
            }
          : item,
      ),
    );

    const { data, error } = await supabase.functions.invoke("resend-email", {
      body: {
        to: notificationItem.recipient,
        subject: notificationItem.subject,
        html: `
          <div style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;color:#0f172a">
            <div style="border:1px solid #e2e8f0;border-radius:18px;padding:24px;background:#ffffff">
              <p style="margin:0 0 8px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#0284c7;font-weight:700">
                TRYBUN · ${notificationItem.type}
              </p>
              <h1 style="margin:0 0 16px;font-size:24px;line-height:1.2">${notificationItem.subject}</h1>
              <div style="font-size:15px;line-height:1.6;color:#334155">
                ${String(notificationItem.message || "").replace(/\n/g, "<br/>")}
              </div>
              <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0" />
              <p style="font-size:12px;color:#64748b;margin:0">Vorlage: ${notificationItem.email_template || "Standard"}</p>
            </div>
          </div>
        `,
      },
    });

    if (error) {
      await supabase
        .from("notifications")
        .update({
          email_status: "failed",
          status: "Fehler",
          email_error: error.message,
          email_last_attempt_at: new Date().toISOString(),
        })
        .eq("id", notificationItem.id);

      setNotifications((prev) =>
        prev.map((item) =>
          item.id === notificationItem.id
            ? {
                ...item,
                email_status: "failed",
                status: "Fehler",
                email_error: error.message,
                email_last_attempt_at: new Date().toISOString(),
              }
            : item,
        ),
      );

      alert(`E-Mail konnte nicht gesendet werden: ${error.message}`);
      return;
    }

    const mailWasAccepted = Boolean(data?.id || data?.success);
    const nextStatus = mailWasAccepted ? "sent" : "failed";
    const nextLabel = mailWasAccepted ? "Gesendet" : "Fehler";
    const nextError = data?.error || data?.message || null;
    const nextSentAt = mailWasAccepted ? new Date().toISOString() : null;
    const nextProviderId = data?.id || data?.resend?.id || null;

    await supabase
      .from("notifications")
      .update({
        email_status: nextStatus,
        status: nextLabel,
        email_sent_at: nextSentAt,
        email_error: nextError,
        email_provider_id: nextProviderId,
        email_last_attempt_at: new Date().toISOString(),
      })
      .eq("id", notificationItem.id);


    setNotifications((prev) =>
      prev.map((item) =>
        item.id === notificationItem.id
          ? {
              ...item,
              email_status: nextStatus,
              status: nextLabel,
              email_sent_at: data?.sentAt || nextSentAt,
              email_error: nextError,
              email_provider_id: nextProviderId,
              email_last_attempt_at: new Date().toISOString(),
            }
          : item,
      ),
    );

    await loadNotifications();

    if (mailWasAccepted) {
      alert("E-Mail wurde gesendet.");
    } else {
      alert(`E-Mail konnte nicht gesendet werden: ${nextError || "Unbekannter Fehler"}`);
    }
  }

  async function updateNotificationStatus(
    notificationId: number,
    nextStatus: string,
  ) {
    const { error } = await supabase
      .from("notifications")
      .update({ status: nextStatus })
      .eq("id", notificationId);

    if (error) {
      alert(`Status konnte nicht geändert werden: ${error.message}`);
      return;
    }

    setNotifications((prev) =>
      prev.map((item) =>
        item.id === notificationId
          ? { ...item, status: nextStatus }
          : item,
      ),
    );
  }

  function resetInvoiceForm() {
    setInvoiceType("Rechnung");
    setInvoiceTicketId("");
    setInvoiceTitle("");
    setInvoiceAmountNet("");
    setInvoiceTaxRate("19");
    setInvoiceStatus("Entwurf");
    setInvoiceNote("");
  }

  function getInvoiceCustomerName(item: InvoiceItem) {
    if (item.customer_id) {
      return getCustomerNameById(item.customer_id);
    }

    const ticket = tickets.find((ticketItem) => ticketItem.id === item.ticket_id);
    return ticket?.customer || "Nicht zugeordnet";
  }


  function getAbnahmeDeviceCategoryLabel(item?: Device | null) {
    if (!item) return "";

    const linkedModel = item.model_id
      ? deviceModels.find((modelItem) => modelItem.id === item.model_id)
      : null;

    return getDeviceModelTypeName(linkedModel) || item.status || "";
  }

  function getAbnahmeNeutralDeviceLabel(item?: Device | null) {
    if (!item) return "Unbekanntes Gerät";

    const manufacturerName =
      item.manufacturer ||
      getManufacturerNameById(item.manufacturer_id) ||
      "";

    const categoryName = getAbnahmeDeviceCategoryLabel(item);

    const modelName =
      getDeviceModelNameById(item.model_id) ||
      item.model ||
      "";

    const deviceName = item.name || modelName || "Unbekanntes Gerät";

    return [manufacturerName, categoryName, modelName || deviceName]
      .filter(Boolean)
      .join(" · ");
  }

  function buildAbnahmeDeviceRow(item: Device): AbnahmeDeviceRow {
    return {
      rowId: `device-${item.id}`,
      deviceId: String(item.id),
      manufacturer:
        item.manufacturer ||
        getManufacturerNameById(item.manufacturer_id) ||
        "",
      model:
        getDeviceModelNameById(item.model_id) ||
        item.model ||
        item.name ||
        "",
      serial: item.serial_number || "",
      result: abnahmeDeviceResult || "OK",
      defects: item.note || "",
    };
  }

  function updateAbnahmeDeviceRow(
    rowId: string,
    field: keyof Omit<AbnahmeDeviceRow, "rowId" | "deviceId">,
    value: string,
  ) {
    setAbnahmeDeviceRows((prev) =>
      prev.map((row) =>
        row.rowId === rowId ? { ...row, [field]: value } : row,
      ),
    );

    if (field === "result") {
      setAbnahmeDeviceResult(value);
    }
  }

  const selectedAbnahmeDevices = abnahmeSelectedDeviceIds
    .map((deviceId) =>
      devices.find((item) => String(item.id) === String(deviceId)) ||
      getAbnahmeLibraryDeviceById(deviceId),
    )
    .filter((item): item is Device => Boolean(item));

  function toggleAbnahmeDevice(deviceId: string) {
    if (!deviceId) return;

    const selectedDevice =
      devices.find((item) => String(item.id) === String(deviceId)) ||
      getAbnahmeLibraryDeviceById(deviceId);
    if (!selectedDevice) return;

    setAbnahmeSelectedDeviceIds((prev) => {
      const exists = prev.includes(deviceId);
      const nextIds = exists
        ? prev.filter((item) => item !== deviceId)
        : [...prev, deviceId];

      const firstDeviceId = nextIds[0] || "";
      setAbnahmeDeviceId(firstDeviceId);

      setAbnahmeDeviceRows((prevRows) => {
        if (exists) {
          return prevRows.filter((row) => row.deviceId !== deviceId);
        }

        if (prevRows.some((row) => row.deviceId === deviceId)) {
          return prevRows;
        }

        return [...prevRows, buildAbnahmeDeviceRow(selectedDevice)];
      });

      if (firstDeviceId) {
        const firstDevice =
          devices.find((item) => String(item.id) === String(firstDeviceId)) ||
          getAbnahmeLibraryDeviceById(firstDeviceId);
        if (firstDevice) {
          setAbnahmeManufacturer(
            firstDevice.manufacturer ||
              getManufacturerNameById(firstDevice.manufacturer_id) ||
              "",
          );
          setAbnahmeModel(
            getDeviceModelNameById(firstDevice.model_id) ||
              firstDevice.model ||
              firstDevice.name ||
              "",
          );
          setAbnahmeSerial(firstDevice.serial_number || "");
          setAbnahmeDefects(firstDevice.note || "");
        }
      } else {
        setAbnahmeManufacturer("");
        setAbnahmeModel("");
        setAbnahmeSerial("");
        setAbnahmeDefects("");
      }

      return nextIds;
    });
  }

