  async function importSparePartsFromFile() {
    if (!isAdmin) return;
    const currentCompany = companyData || (await loadCompany(session?.user?.id));
    if (!currentCompany?.id) { alert("Ihre Firmenzuordnung konnte nicht geladen werden."); return; }

    const rows = sparePartImportRows
      .map((row, index) => ({ row, rowNumber: index + 2, name: importValue(row, sparePartImportMapping, "name") }))
      .filter((x) => x.name);

    if (!rows.length) { alert("Keine gültigen Ersatzteilzeilen. Bitte Ersatzteil/Bezeichnung zuordnen."); return; }
    if (!confirm(`${rows.length} Ersatzteilzeile(n) in den Ersatzteilstamm von ${currentCompany.name} importieren?`)) return;

    setSparePartImportBusy(true); setSparePartImportMessage("Import läuft …");
    let created = 0, updated = 0, skipped = 0, manufacturersCreated = 0, suppliersCreated = 0;
    const errors: string[] = [];

    const [
      { data: mans, error: me },
      { data: sups, error: se },
      { data: parts, error: pe },
    ] = await Promise.all([
      supabase.from("manufacturers").select("*").eq("company_id", currentCompany.id),
      supabase.from("suppliers").select("*").eq("company_id", currentCompany.id),
      supabase.from("spare_parts").select("*").eq("company_id", currentCompany.id),
    ]);

    if (me || se || pe) {
      setSparePartImportBusy(false);
      alert("Ersatzteildaten konnten nicht vorbereitet werden. Bitte versuche es erneut.");
      return;
    }

    const manMap = new Map<string, Manufacturer>();
    (mans || []).forEach((m: any) => manMap.set(normalizeMasterKey(m.name), m));
    const supplierMap = new Map<string, Supplier>();
    (sups || []).forEach((s: any) => supplierMap.set(normalizeMasterKey(s.name), s));

    const skuMap = new Map<string, SparePart>();
    const nameMap = new Map<string, SparePart>();
    (parts || []).forEach((p: any) => {
      if (p.sku) skuMap.set(normalizeMasterKey(p.sku), p);
      nameMap.set(`${p.manufacturer_id || 0}::${p.supplier_id || 0}::${normalizeMasterKey(p.name)}`, p);
    });

    for (const item of rows) try {
      const r = item.row;
      const manufacturerName = importValue(r, sparePartImportMapping, "manufacturer");
      const supplierName = importValue(r, sparePartImportMapping, "supplier");

      let man: Manufacturer | null = null;
      if (manufacturerName) {
        man = manMap.get(normalizeMasterKey(manufacturerName)) || null;
        if (!man) {
          const { data, error } = await supabase.from("manufacturers")
            .insert([{ company_id: currentCompany.id, name: manufacturerName }]).select("*").single();
          if (error) throw error;
          man = data as Manufacturer;
          manMap.set(normalizeMasterKey(manufacturerName), man);
          manufacturersCreated++;
        }
      }

      let supplier: Supplier | null = null;
      if (supplierName) {
        supplier = supplierMap.get(normalizeMasterKey(supplierName)) || null;
        if (!supplier) {
          const { data, error } = await supabase.from("suppliers")
            .insert([{ company_id: currentCompany.id, name: supplierName }]).select("*").single();
          if (error) throw error;
          supplier = data as Supplier;
          supplierMap.set(normalizeMasterKey(supplierName), supplier);
          suppliersCreated++;
        }
      }

      const sku = importValue(r, sparePartImportMapping, "sku");
      const nameKey = `${man?.id || 0}::${supplier?.id || 0}::${normalizeMasterKey(item.name)}`;
      const found = (sku ? skuMap.get(normalizeMasterKey(sku)) : null) || nameMap.get(nameKey);

      const payload = {
        company_id: currentCompany.id,
        name: item.name,
        sku: sku || null,
        manufacturer_id: man?.id || null,
        supplier_id: supplier?.id || null,
        manufacturer_part_number: importValue(r, sparePartImportMapping, "manufacturer_part_number") || null,
        stock: parseImportNumber(importValue(r, sparePartImportMapping, "stock"), 0),
        min_stock: parseImportNumber(importValue(r, sparePartImportMapping, "min_stock"), 0),
        unit: importValue(r, sparePartImportMapping, "unit") || "Stück",
        purchase_price: parseImportNumber(importValue(r, sparePartImportMapping, "purchase_price"), 0),
        storage_location: importValue(r, sparePartImportMapping, "storage_location") || null,
        note: importValue(r, sparePartImportMapping, "note") || null,
      };

      if (found && sparePartImportDuplicateMode === "skip") { skipped++; continue; }

      if (found) {
        const { error } = await supabase.from("spare_parts").update(payload)
          .eq("id", found.id).eq("company_id", currentCompany.id);
        if (error) throw error;
        updated++;
      } else {
        const { data, error } = await supabase.from("spare_parts").insert([payload]).select("*").single();
        if (error) throw error;
        const inserted = data as SparePart;
        if (sku) skuMap.set(normalizeMasterKey(sku), inserted);
        nameMap.set(nameKey, inserted);
        created++;
      }
    } catch (error: any) {
      errors.push(`Zeile ${item.rowNumber}: konnte nicht importiert werden.`);
    }

    await loadManufacturers();
    await loadServiceParts();
    setSparePartImportBusy(false);
    const summary = `${created} Ersatzteile neu · ${updated} aktualisiert · ${skipped} übersprungen · ${manufacturersCreated} Hersteller neu · ${suppliersCreated} Lieferanten neu${errors.length ? ` · ${errors.length} Fehler` : ""}`;
    setSparePartImportMessage(summary);
    alert(`Ersatzteilimport abgeschlossen.\n${summary}${errors.length ? `\n\n${errors.slice(0, 8).join("\n")}` : ""}`);
  }

  const role = userProfile?.role || null;
  const isAdmin = role === "admin";
  const isTechnician = role === "technician";
  const isCustomer = role === "customer";
  const canCreateOrEditMasterData = isAdmin || isTechnician;
  const canPlanDispatch = isAdmin;

  const visibleDocumentCategoriesForRole = isCustomer
    ? documentCategories.filter((category) => customerVisibleDocumentCategories.includes(category))
    : documentCategories;

  const uploadDocumentCategoriesForRole = isCustomer
    ? customerUploadDocumentCategories
    : documentCategories.filter((category) => category !== "Alle");

  const todayDateString = new Date().toISOString().split("T")[0];

  function getMaintenanceReminderLevel(plan: MaintenancePlan) {
    const dueState = getMaintenanceDueState(plan);
    const days = dueState.days;

    if (days <= 1 && !plan.reminder_1_sent_at) return { level: 1, field: "reminder_1_sent_at", label: "1 Tag vorher" };
    if (days <= 7 && !plan.reminder_7_sent_at) return { level: 7, field: "reminder_7_sent_at", label: "7 Tage vorher" };
    if (days <= 14 && !plan.reminder_14_sent_at) return { level: 14, field: "reminder_14_sent_at", label: "14 Tage vorher" };
    if (days <= 30 && !plan.reminder_30_sent_at) return { level: 30, field: "reminder_30_sent_at", label: "30 Tage vorher" };

    return null;
  }

  const maintenanceAutomationCandidates = useMemo(() => {
    return maintenancePlans
      .filter((plan) => String(plan.status || "").toLowerCase() !== "abgeschlossen")
      .filter((plan) => plan.reminder_enabled !== false)
      .filter((plan) => Boolean(getMaintenanceReminderLevel(plan)))
      .sort((a, b) => getMaintenanceDueState(a).days - getMaintenanceDueState(b).days)
      .slice(0, 50);
  }, [maintenancePlans]);

  const maintenanceAutomationStats = useMemo(() => {
    const today = new Date().toISOString().split("T")[0];

    return {
      dueToday: maintenancePlans.filter((plan) => getMaintenanceDueState(plan).days === 0).length,
      automationReady: maintenanceAutomationCandidates.length,
      sentToday: notifications.filter((item) => {
        const sentDate = String(item.email_sent_at || item.email_last_attempt_at || "").slice(0, 10);
        return item.type === "Wartungserinnerung" && sentDate === today && (item.email_status || "").toLowerCase() === "sent";
      }).length,
      failed: notifications.filter((item) => item.type === "Wartungserinnerung" && (item.email_status || "").toLowerCase() === "failed").length,
    };
  }, [maintenancePlans, maintenanceAutomationCandidates, notifications]);

  const maintenanceMailCandidates = useMemo(() => {
    return maintenancePlans
      .filter((plan) => String(plan.status || "").toLowerCase() !== "abgeschlossen")
      .filter((plan) => plan.reminder_enabled !== false)
      .filter((plan) => {
        const dueState = getMaintenanceDueState(plan);
        const daysBefore = Math.max(1, Number(plan.reminder_days_before || 14));

        return dueState.days <= daysBefore && dueState.days <= 14;
      })
      .filter((plan) => {
        if (!plan.last_reminder_sent_at) return true;

        const lastSent = new Date(plan.last_reminder_sent_at);
        const now = new Date();
        const diffDays = Math.floor((now.getTime() - lastSent.getTime()) / (1000 * 60 * 60 * 24));

        return diffDays >= Math.max(1, Number(plan.reminder_days_before || 14));
      })
      .sort((a, b) => getMaintenanceDueState(a).days - getMaintenanceDueState(b).days)
      .slice(0, 25);
  }, [maintenancePlans]);

  const openAdminTickets = visibleRoleTickets.filter(
    (ticket) =>
      ticket.status !== "Abgeschlossen" &&
      ticket.status !== "Erledigt" &&
      ticket.status !== "Storniert",
  );

  const sortedOpenAdminTickets = [...openAdminTickets].sort((a, b) => {
    const priorityRank: Record<string, number> = { Hoch: 0, Mittel: 1, Niedrig: 2 };
    const statusRank: Record<string, number> = {
      Offen: 0,
      Zugewiesen: 1,
      "Termin vereinbart": 2,
      "In Bearbeitung": 3,
      "Wartet auf Ersatzteil": 4,
      "Wartet auf Ersatzteile": 4,
      "Wartet auf Kundenfreigabe": 5,
    };

    const priorityDiff =
      (priorityRank[a.priority] ?? 9) - (priorityRank[b.priority] ?? 9);
    if (priorityDiff !== 0) return priorityDiff;

    const statusDiff = (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9);
    if (statusDiff !== 0) return statusDiff;

    const dateA = `${a.service_date || "9999-12-31"} ${a.service_time || "99:99"}`;
    const dateB = `${b.service_date || "9999-12-31"} ${b.service_time || "99:99"}`;
    return dateA.localeCompare(dateB);
  });

  const todaysAdminTickets = visibleRoleTickets
    .filter((ticket) => ticket.service_date === new Date().toISOString().split("T")[0])
    .sort((a, b) => {
      const timeA = a.service_time || "99:99";
      const timeB = b.service_time || "99:99";
      return timeA.localeCompare(timeB);
    });

  const overdueAdminMaintenancePlans = maintenancePlans.filter((plan) => {
    if (!plan.next_due) return false;
    if ((plan.status || "Geplant") === "Abgeschlossen") return false;

    const today = new Date();
    const dueDate = new Date(plan.next_due);

    today.setHours(0, 0, 0, 0);
    dueDate.setHours(0, 0, 0, 0);

    return dueDate.getTime() < today.getTime();
  });

  const activeServiceParts = serviceParts.filter((part) => !part.is_archived);

